  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-page: #0f1117;
  --bg-card: #1a1d27;
  --bg-card-border: #2e3247;
  --color-text: #e2e4ef;
  --color-text-muted: #8b8fa8;
  --color-accent: #6c63ff;
  --color-accent-hover: #857dff;
  --color-accent-active: #554dcc;
  --color-error: #f87171;
  --color-success: #4ade80;
  --focus-ring: 0 0 0 3px rgba(108, 99, 255, 0.55);
  --radius: 10px;
  --transition: 150ms ease;
}

body {
  min-height: 100vh;
  background: var(--bg-page);
  color: var(--color-text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -999px;
  left: 1rem;
  background: var(--color-accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus {
  top: 1rem;
  outline: none;
  box-shadow: var(--focus-ring);
}

/* Card */
.card {
  width: 100%;
  max-width: 480px;
  background: var(--bg-card);
  border: 1px solid var(--bg-card-border);
  border-radius: 16px;
  padding: 2.5rem 2rem;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
}

.card-header {
  margin-bottom: 1.75rem;
  text-align: center;
}

.card-header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--color-text);
}

.card-header p {
  margin-top: 0.4rem;
  font-size: 0.9rem;
  color: var(--color-text-muted);
}

/* Form field wrapper */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-bottom: 1.75rem;
}

/* Checkbox row */
.checkbox-row {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
}

/* Hide native checkbox visually but keep it accessible */
.checkbox-input {
  position: absolute;
  opacity: 0;
  width: 1.25rem;
  height: 1.25rem;
  margin: 0;
  cursor: pointer;
}

/* Custom checkbox */
.checkbox-custom {
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  border: 2px solid var(--bg-card-border);
  border-radius: 4px;
  background: transparent;
  transition: background var(--transition), border-color var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 0.15rem;
  pointer-events: none;
}

/* Checkmark SVG */
.checkbox-custom svg {
  display: none;
  width: 0.75rem;
  height: 0.75rem;
  color: #fff;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.checkbox-input:checked + .checkbox-custom {
  background: var(--color-accent);
  border-color: var(--color-accent);
}

.checkbox-input:checked + .checkbox-custom svg {
  display: block;
}

.checkbox-input:focus-visible + .checkbox-custom {
  outline: none;
  box-shadow: var(--focus-ring);
  border-color: var(--color-accent);
}

/* Checkbox label text */
.checkbox-label {
  font-size: 0.9375rem;
  color: var(--color-text);
  cursor: pointer;
  user-select: none;
}

.checkbox-label a {
  color: var(--color-accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.checkbox-label a:hover {
  color: var(--color-accent-hover);
}

.checkbox-label a:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* Helper text */
.helper-text {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  padding-left: calc(1.25rem + 0.75rem); /* align under label */
}

/* Error message */
.error-message {
  font-size: 0.8125rem;
  color: var(--color-error);
  padding-left: calc(1.25rem + 0.75rem);
  display: none;
}

.error-message[aria-hidden="false"] {
  display: block;
}

/* Checkbox invalid state */
.form-field[data-invalid="true"] .checkbox-custom {
  border-color: var(--color-error);
}

/* Submit button */
.btn-submit {
  width: 100%;
  padding: 0.75rem 1.5rem;
  background: var(--color-accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition);
  letter-spacing: 0.01em;
}

.btn-submit:hover {
  background: var(--color-accent-hover);
}

.btn-submit:active {
  background: var(--color-accent-active);
  transform: scale(0.98);
}

.btn-submit:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* Success message */
.success-message {
  display: none;
  align-items: center;
  gap: 0.6rem;
  margin-top: 1.25rem;
  padding: 0.75rem 1rem;
  background: rgba(74, 222, 128, 0.1);
  border: 1px solid rgba(74, 222, 128, 0.35);
  border-radius: var(--radius);
  color: var(--color-success);
  font-size: 0.9rem;
  font-weight: 500;
}

.success-message[aria-hidden="false"] {
  display: flex;
}

.success-message svg {
  flex-shrink: 0;
  width: 1.1rem;
  height: 1.1rem;
}

/* Forced colors support */
@media (forced-colors: active) {
  .checkbox-custom {
    border: 2px solid ButtonText;
    background: Canvas;
  }

  .checkbox-input:checked + .checkbox-custom {
    background: Highlight;
    border-color: Highlight;
  }

  .checkbox-input:focus-visible + .checkbox-custom {
    outline: 2px solid ButtonText;
    box-shadow: none;
  }

  .btn-submit {
    background: ButtonFace;
    color: ButtonText;
    border: 1px solid ButtonText;
    forced-color-adjust: none;
  }
}

/* Reflow: narrow viewports */
@media (max-width: 340px) {
  .card {
    padding: 1.75rem 1.25rem;
  }
}
