+    consentInput.setAttribute("aria-describedby", "consent-helper consent-error");
+  }
+
+  function clearInvalid() {
+    delete consentField.dataset.invalid;
+    errorMsg.setAttribute("aria-hidden", "true");
+    consentInput.setAttribute("aria-invalid", "false");
+    consentInput.setAttribute("aria-describedby", "consent-helper");
+  }
+
+  consentInput.addEventListener("change", function () {
+    if (this.checked) {
+      clearInvalid();
+    }
+  });
